dtsPropsFor.Spec:
items: {
    /** Field name, e.g. `feedstock` or `permanence`. Rendered uppercase. */
    label: React.ReactNode;
    /** The reading. Monospaced and tabular - keep it terse. */
    value: React.ReactNode;
    /** Print the value in the accent colour, for the one figure that matters. */
    accent?: boolean;
  }[];
  /** `rows` is a ruled list (label left, value right). `columns` lays the pairs
   *  out side by side under hairline verticals - use it beneath a big number. */
  layout?: "rows" | "columns";

dtsPropsFor.Table:
columns: {
    /** Stable key. Used for React keys and as the default accessor. */
    key: string;
    /** Column heading. Rendered uppercase and tracked. */
    header: React.ReactNode;
    /** Cell renderer. Defaults to `row[key]`. */
    render?: (row: any, index: number) => React.ReactNode;
    /** Right-align in tabular figures - use for every number. */
    numeric?: boolean;
    /** Fixed column width, e.g. `"160px"` or `"20%"`. */
    width?: string;
  }[];
  rows: Record<string, React.ReactNode>[];
  rowKey?: (row: any, index: number) => string | number;
  /** Tint alternating rows. */
  striped?: boolean;
  /** Highlight the row under the cursor. */
  hoverable?: boolean;
  /** Tighter vertical rhythm, for dense data views. */
  compact?: boolean;
  caption?: React.ReactNode;
  emptyMessage?: React.ReactNode;

dtsPropsFor.Select:
options?: {
    /** Submitted value. */
    value: string;
    /** Visible text. */
    label: string;
    disabled?: boolean;
  }[];
  label?: React.ReactNode;
  hint?: React.ReactNode;
  /** Error message. Its presence marks the control invalid. */
  error?: React.ReactNode;
  size?: "sm" | "md" | "lg";
  required?: boolean;
  /** Leading empty choice, e.g. `"Select a project"`. */
  placeholder?: string;
  fullWidth?: boolean;
  defaultValue?: string;
  value?: string;
  onChange?: React.ChangeEventHandler<HTMLSelectElement>;
  disabled?: boolean;
  name?: string;

dtsPropsFor.RadioGroup:
/** Shared form name for the options. */
  name: string;
  options: {
    value: string;
    label: React.ReactNode;
    /** Secondary line under the label. */
    description?: React.ReactNode;
    disabled?: boolean;
  }[];
  /** Uncontrolled initial selection. */
  defaultValue?: string;
  /** Controlled selection. Pair with `onChange`. */
  value?: string;
  onChange?: (value: string) => void;
  /** Uppercase micro-label above the set. */
  legend?: React.ReactNode;
  direction?: "vertical" | "horizontal";

dtsPropsFor.Tabs:
items: {
    /** Stable id, used as the selected value. */
    id: string;
    /** Tab text. Rendered uppercase and widely tracked. */
    label: React.ReactNode;
    /** Small count beside the label. */
    badge?: React.ReactNode;
    disabled?: boolean;
    /** Panel content for this tab. */
    content?: React.ReactNode;
  }[];
  defaultValue?: string;
  value?: string;
  onChange?: (id: string) => void;
  /** `underline` is the editorial default; `pills` the segmented control. */
  variant?: "underline" | "pills";
